// ╭──────────────────────────────────────────────────────────╮
// │                                                          │
// │ Raymarching shader inspired by my previous creations.    │
// │     donut.glsl: https://www.shadertoy.com/view/MX3cDf    │
// │     squorus: https://www.desmos.com/3d/frfxofojic        │
// │                                                          │
// │ | squorus.glsl | taep96 | 2025/1/12 |                    │
// │                                                          │
// ╰──────────────────────────────────────────────────────────╯

// Calculate the distance from the pos to the squorus.
float sdSquorus(vec3 pos, vec2 radii, vec2 squirclenesses) {
    float xyTerm = pow(pow(abs(pos.x), squirclenesses.x) + pow(abs(pos.y), squirclenesses.x), 1.0 / squirclenesses.x) - radii.x;
    float dist = pow(pow(abs(xyTerm), squirclenesses.y) + pow(abs(pos.z), squirclenesses.y), 1.0 / squirclenesses.y) - radii.y;

    return dist;
}

// Create a 2D rotation matrix for a given angle.
mat2 rotation2D(float angle) {
    float s = sin(angle), c = cos(angle);
    return mat2(c, - s, s, c);
}

float distanceField(vec3 pos, vec4 mouse, float time) {
    // Sensetivity factor for mouse movement.
    const float sensitivity = 3.0;

    // Normalize the coordinates.
    vec2 mousePos = (iMouse.xy * 2.0 - iResolution.xy) / iResolution.y * sensitivity;

    // If the left mouse button is pressed, then rotate -
    if (iMouse.z > 0.0) {
        // based on the mouse position,
        pos.xy *= rotation2D(-mousePos.x);
        pos.yz *= rotation2D(-mousePos.y);
    } else {
        // otherwise, on the time.
        pos.xz *= rotation2D(time * 2.0);
        pos.xy *= rotation2D(time);
    }

    // Torus with major and minor radii of 2 and 1.
    return sdSquorus(pos, vec2(2.0, 1.0), vec2(3.0, 3.0));
}

vec3 surfaceNormal(vec3 pos, vec4 mouse, float time) {
    // Approximate the surface normal using central differences on the distance field.
    const vec2 epsilon = vec2(0.001, 0.0);
    return normalize(
        vec3(
            distanceField(pos + epsilon.xyy, mouse, time) - distanceField(pos - epsilon.xyy, mouse, time),
            distanceField(pos + epsilon.yxy, mouse, time) - distanceField(pos - epsilon.yxy, mouse, time),
            distanceField(pos + epsilon.yyx, mouse, time) - distanceField(pos - epsilon.yyx, mouse, time)
        )
    );
}

void mainImage(out vec4 fragCol, in vec2 fragCoord) {
    // Normalize the coordinates.
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Set up the camera pos and direction.
    vec3 rayPos = vec3(0.0, 0.0, - 6.0);
    vec3 rayDir = normalize(vec3(uv, 1.0));

    // Initialize raymarching parameters.
    float rayDist = 0.0;
    float stepCount = 0.0;

    // Raymarch the scene by iteratively advancing along the ray.
    for(int i = 0; i < 100; i ++ ) {
        vec3 currPos = rayPos + rayDir * rayDist;
        float dist = distanceField(currPos, iMouse, iTime);

        // Early return if close enough or too far away.
        if (dist < 0.001)break;
        if (rayDist > 20.0) { rayDist = -1.0; break; }

        rayDist += dist;
        stepCount ++ ;
    }

    // Initialize the final color.
    vec3 finalColor = vec3(0.0);

    // If the ray hit the scene, calculate shading and lighting.
    if (rayDist > 0.0) {
        vec3 hitPos = rayPos + rayDir * rayDist;
        vec3 normal = surfaceNormal(hitPos, iMouse, iTime);

        // Basic diffuse shading
        vec3 lightDir = normalize(vec3(1.0, 2.0, - 3.0));
        float diff = max(0.0, dot(normal, lightDir));

        // Apply shading using the diffuse intensity.
        float shading = pow(diff * 0.5 + 0.5, 3.0);

        // Apply color based on shading.
        finalColor = vec3(1.0, 0.2, 0.2) * shading;

        // Add ambient occlusion effect based on step count.
        finalColor *= 1.0 - stepCount / 100.0;
    }

    // Output the final color as the fragment color.
    fragCol = vec4(finalColor, 1.0);
}
